test("--installer writes its own file, keeps the components of that architecture and labels installer-only ones", (t) => {
  const dir = work(t);
  const r = gen(dir, "--write", ["--installer", "x64"]);
  assert.equal(r.code, 0, r.out);
  assert.ok(!existsSync(join(dir, OUT)), "the plain file was written too");
  const text = read(dir, "THIRD-PARTY-NOTICES.x64.md");
  assert.equal(text, readFileSync(join(FIXTURES, "expected", "THIRD-PARTY-NOTICES.x64.md.golden"), "utf8"));
  assert.ok(text.includes("Inter 4.1") && text.includes("Inno Setup loader"));
  assert.ok(!text.includes("Fixture DLL library"), "an arm64-only component is in the x64 file");
  assert.ok(text.includes(`- ${INSTALLER_ONLY}\n`), "an installer-only component is not labelled");
});

