// A crate added to the fixture report, with its source folder.
function addCrate(dir, name, version, licence, files = {}) {
  editJson(dir, "cargo-about.json", (j) => {
    j.crates.push({ package: { name, version, source: "registry+https://github.com/rust-lang/crates.io-index", repository: null, license: licence, manifest_path: `registry/${name}-${version}/Cargo.toml` }, license: licence });
  });
  put(dir, `registry/${name}-${version}/Cargo.toml`, `[package]\nname = "${name}"\nversion = "${version}"\n`);
  for (const [path, body] of Object.entries(files)) put(dir, `registry/${name}-${version}/${path}`, body);
}

test("names are sorted by code unit, not by locale or case: Zeta before alpha, LICENSE before copying", (t) => {
  const dir = work(t);
  addCrate(dir, "Zeta", "1.0.0", "MIT", { LICENSE: "zeta licence text\n", copying: "zeta copying text\n" });
  addCrate(dir, "alpha", "1.0.0", "MIT", { LICENSE: "alpha licence text\n" });
  assert.equal(gen(dir).code, 0);
  const text = read(dir, OUT);
  const row = (n) => text.indexOf(`| ${n} | 1.0.0 | MIT |`);
  assert.ok(row("Zeta") > 0 && row("alpha") > row("Zeta"), `table rows: Zeta ${row("Zeta")}, alpha ${row("alpha")}`);
  const head = (h) => text.indexOf(`### ${h}\n`);
  assert.ok(head("Zeta 1.0.0 — LICENSE") > 0 && head("Zeta 1.0.0 — copying") > head("Zeta 1.0.0 — LICENSE"), "LICENSE must come before copying");
  assert.ok(head("alpha 1.0.0 — LICENSE") > head("Zeta 1.0.0 — copying"), "alpha's file must come after Zeta's, by code unit");
});

