test("the schema file in the template is itself a schema the script understands (no unknown keyword)", () => {
  const schema = JSON.parse(readFileSync(SCHEMA, "utf8"));
  const known = new Set(["$schema", "title", "description", "type", "required", "additionalProperties", "properties", "$defs", "$ref", "items", "enum", "const", "pattern", "minLength", "minItems", "oneOf", "uniqueItems"]);
  const walk = (node, path) => {
    if (Array.isArray(node)) return node.forEach((n, i) => walk(n, `${path}[${i}]`));
    if (node === null || typeof node !== "object") return;
    for (const [k, v] of Object.entries(node)) {
      if (path.endsWith("properties") || path.endsWith("$defs")) walk(v, `${path}.${k}`);
      else {
        assert.ok(known.has(k), `${path}.${k} is a keyword the generator's validator does not know`);
        walk(v, `${path}.${k}`);
      }
    }
  };
  walk(schema, "#");
});

