test("the synthesized text that is still printed names the authors of each crate that uses it, and says what it is", (t) => {
  const dir = work(t);
  assert.equal(gen(dir).code, 0);
  const printed = section(read(dir, OUT), "## Licence texts reported by cargo-about", "## Notice and licence files from the crate sources");
  assert.ok(printed.includes("Used by: d-crate 2.0.0 (authors: D Author <d@example.invalid>)\n"), printed);
  assert.ok(printed.includes(TEMPLATE_NOTE), "the note on the template is not the one the golden file has");
  assert.ok(printed.includes("Copyright (c) <year> <copyright holders>"), "the template text itself is no longer written");
  assert.equal(printed.split(TEMPLATE_NOTE_START).length - 1, 1, "a text that cargo-about read from a file got the template line");
  assert.ok(!/ships no licence file|because the crate/.test(printed), "the note claims a reason that is not true of every crate it lists (the sweep may hold a licence file of the crate)");
  assert.ok(!/Used by: a-crate[^\n]*authors/.test(printed), "a crate whose own text was read got an authors line");
});

