  const row = "| font.woff2 | Someone | OFL-1.1 |\n<!-- END GENERATED FROM assets.toml -->";
  edit(dir, OUT, (s) => s.replace("<!-- END GENERATED FROM assets.toml -->", row));
  put(dir, OUT, read(dir, OUT).replace(/\n/g, "\r\n"));
  assert.equal(gen(dir).code, 0);
  const text = read(dir, OUT);
  assert.ok(text.includes(row), "the block of a CRLF copy was dropped");
  assert.ok(!text.includes("\r"), "the file was not written with LF");
  put(dir, OUT, text.replace(/\n/g, "\r\n"));
  assert.equal(gen(dir, "--write", ["--installer", "x64"]).code, 0);
