  assert.ok(text.includes(`- a-crate 1.2.3 — LICENSE.third: ${COMMITTED_NOTE}\n`), "the first holder lost its note");
  assert.ok(text.includes(`- d-crate 2.0.0 — LICENSE.third: ${COMMITTED_NOTE}\n`), "the second holder lost its note");
  assert.equal(text.split("Copyright 2019 The Third Authors").length - 1, 1, "the shared text is written once per holder");
  // the same file as an entry for each crate
  const other = work(t);
  editJson(other, "policy.json", (j) => (j.crate_texts = [crateEntry({ package: "d-crate", version: "2.0.0" }), crateEntry({ package: "a-crate", version: "1.2.3" })]));
