// ---- closing round: line ends on every path that prints a text ----------------------------------------------------
// Four paths print a text that the sweep does not read: cargo-about's own licence texts, the policy's platform texts,
// the pinned NuGet licence texts and the inventory's noticeTexts. Real inputs on them carry CR: the template's own
// .github/licence-texts/inno-setup-license.txt has 31 CR bytes and pascal-script-LICENSE.txt 18 (tr -cd '\r' | wc -c,
// 2026-11-25). So one fixture text of each path has CRLF line ends: the Apache-2.0 text of cargo-about.json (a JSON
// string), platform/license.txt, licence-texts/MPL-2.0.txt and inventory/texts/inno/license.txt; the last two also
// start with a UTF-8 byte-order mark. fixtures/notices/.gitattributes (`* -text`) keeps those bytes in a checkout.

test("every text the notices print has LF line ends and no byte-order mark, on each path that the sweep does not read", (t) => {
  const dir = work(t);
  // a fixture saved again with LF would make this case prove nothing, so the fixtures are checked first
  assert.ok(JSON.parse(read(dir, "cargo-about.json")).licenses.find((l) => l.id === "Apache-2.0").text.includes("\r\n"), "cargo-about.json's Apache-2.0 text has no CRLF");
  for (const [rel, bom] of [["platform/license.txt", false], ["licence-texts/MPL-2.0.txt", true], ["inventory/texts/inno/license.txt", true]]) {
    const bytes = readFileSync(join(dir, rel));
    assert.ok(bytes.includes(0x0d), `the fixture ${rel} has no CR`);
    assert.equal(bytes.subarray(0, 3).equals(Buffer.from([0xef, 0xbb, 0xbf])), bom, `the fixture ${rel}: byte-order mark`);
  }
  assert.equal(gen(dir).code, 0);
  const text = read(dir, OUT);
  assert.ok(!text.includes("\r"), "a carriage return reached the output");
  assert.ok(!text.includes("﻿"), "a byte-order mark reached the output");
  const printed = [
    ["cargo-about's text", "## Licence texts reported by cargo-about", "## Notice and licence files from the crate sources", "```text\nApache License\nVersion 2.0, January 2004 (fixture text, not the real licence)\n```\n"],
    ["the pinned NuGet text", "## Licence texts for NuGet packages", "## Notice and licence files from the NuGet packages", "```text\nMozilla Public License Version 2.0 (fixture text, not the real licence)\n```\n"],
    ["the inventory's notice text", "## Components that are not crates", "## Platform components", "```text\nInno Setup License (fixture text)\nCopyright (C) 1997-2026 Jordan Russell. All rights reserved.\n```\n"],
    ["the platform text", "## Platform components", "## Attributions for assets", "```text\nFixture separate program licence text.\n```\n"],
  ];
  for (const [what, from, to, fencedText] of printed) assert.ok(section(text, from, to).includes(fencedText), `${what} is not printed with LF line ends and without its byte-order mark`);
  // the per-installer file prints the same texts
  assert.equal(gen(dir, "--write", ["--installer", "x64"]).code, 0);
  const installer = read(dir, "THIRD-PARTY-NOTICES.x64.md");
  assert.ok(!installer.includes("\r") && !installer.includes("﻿"), "a carriage return or a byte-order mark reached the x64 file");
});

