test("when no crate source holds a notice or licence file the section says so: an UNLICENSE file is not swept", (t) => {
  const dir = work(t);
  // c-crate alone: cargo-about read its Unlicense text from the file UNLICENSE, whose name the sweep does not match
  put(dir, "registry/c-crate-3.1.0/UNLICENSE", "This is free and unencumbered software released into the public domain (fixture text).\n");
  editJson(dir, "cargo-about.json", (j) => {
    j.crates = j.crates.filter((c) => c.package.name === "c-crate");
    j.licenses = j.licenses.filter((l) => l.id === "Unlicense");
  });
  const r = genOne(dir, RUST_ONLY);
  assert.equal(r.code, 0, r.out);
  const text = read(dir, OUT);
  assert.ok(text.includes("## Notice and licence files from the crate sources\n\nNo crate source holds such a file.\n\n## Components that are not crates\n"), section(text, "## Notice and licence files", "## Platform components"));
});

test("a policy with no platform entries writes no platform heading", (t) => {
  const dir = work(t);
  editJson(dir, "policy.json", (j) => (j.platform = []));
  const r = gen(dir);
  assert.equal(r.code, 0, r.out);
  const text = read(dir, OUT);
  assert.ok(!text.includes("## Platform components"), "an empty platform section got its heading");
  assert.ok(text.includes("This installer is made using RemObjects Pascal Script"), "the inventory's about line went with the platform entries");
});

test("a contains[] nested past the sixth heading level stays at ######, the deepest heading that Markdown has", (t) => {
  const dir = work(t);
  editJson(dir, "inventory/bundled-components.json", (j) => {
    // Inno Setup is at level 3 and Pascal Script, its contains[], at level 4; four more levels go below it
    let parent = j.components.find((c) => c.id === "inno-setup-loader").contains[0];
    for (const level of [5, 6, 7, 8]) {
      const sub = { ...structuredClone(parent), id: `nested-${level}`, component: `Nested level ${level}` };
      delete sub.contains;
      parent.contains = [sub];
      parent = sub;
    }
  });
  const r = gen(dir);
  assert.equal(r.code, 0, r.out);
  const text = read(dir, OUT);
  for (const [level, hashes] of [[5, "#####"], [6, "######"], [7, "######"], [8, "######"]]) {
    assert.ok(text.includes(`\n${hashes} Nested level ${level} as compiled into Inno Setup 7.1.1\n`), `level ${level} is not a ${hashes} heading`);
  }
  assert.ok(!/^#{7,} /m.test(text), "a heading deeper than six levels was written");
});

test("a crate_texts file that is null or not an object is a named problem, not a crash", (t) => {
  const needs = /crate_texts\[0\]: a committed crate text needs package, version and files \(a non-empty list of \{ path, sha256 \}\)/;
  const cases = [
    ["null", [null]],
    ["null after a good file", [{ path: D_MIT, sha256: D_MIT_SHA }, null]],
    ["a path as a bare string", [D_MIT]],
  ];
  for (const [name, files] of cases) {
    const dir = work(t);
    editJson(dir, "policy.json", (j) => (j.crate_texts[0].files = files));
    const r = gen(dir);
    assert.equal(r.code, 1, `${name}: ${r.out}`);
    assert.match(r.out, needs, name);
    assert.ok(!/TypeError|at .*generate-notices\.mjs/.test(r.out), `${name}: the generator crashed instead of reporting`);
  }
});

test("a path that the policy or the inventory writes with backslashes names the same file, and the notices do not change", (t) => {
  const dir = work(t);
  assert.equal(gen(dir).code, 0);
  const slashed = read(dir, OUT);
  // a committed crate text is headed by its file name alone, whichever separator its path uses
  assert.match(slashed, /### d-crate 2\.0\.0 — LICENSE-MIT\n/);
  const back = (p) => p.replaceAll("/", "\\");
  editJson(dir, "policy.json", (j) => {
    for (const f of j.crate_texts[0].files) f.path = back(f.path);
    for (const e of j.platform) e.licence_file = back(e.licence_file);
    for (const e of j.licence_texts) e.licence_file = back(e.licence_file);
  });
  editJson(dir, "inventory/bundled-components.json", (j) => {
    const walk = (list) => {
      for (const c of list) {
        for (const n of c.noticeTexts) n.file = back(n.file);
        walk(c.contains ?? []);
      }
    };
    walk(j.components);
  });
  const r = gen(dir);
  assert.equal(r.code, 0, r.out);
  assert.equal(read(dir, OUT), slashed, "a path written with backslashes changed the notices");
  assert.equal(gen(dir, "--check").code, 0);
});
